<?php
function market_multi(string $key,array $allowed): array {$raw=$_GET[$key]??[];$raw=is_array($raw)?$raw:[$raw];return array_values(array_unique(array_slice(array_filter($raw,fn($v)=>is_string($v)&&isset($allowed[$v])),0,30)));}
$catalogue=catalogue_materials();$commerce=commerce_readiness();$materialAllowed=[];foreach($catalogue as $m){$materialAllowed[(string)$m['id']]=true;}
$govs=market_multi('governorate',array_fill_keys(array_keys(governorates()),true));$materials=market_multi('material',$materialAllowed);$subcategories=market_multi('subcategory',array_fill_keys(array_keys(material_subcategories()),true));$grade=is_string($_GET['grade']??null)?$_GET['grade']:'';
$rows=[];$p=[];$where="b.status='published' AND b.quantity_g>b.reserved_g AND m.active=1 AND h.active=1 AND m.slug IN ('rice-straw','wheat-straw','corn-residues','sugarcane-bagasse')";
foreach([['b.material_id',$materials],['h.governorate',$govs],['b.subcategory',$subcategories]] as [$column,$values]){if($values){$where.=' AND '.$column.' IN ('.implode(',',array_fill(0,count($values),'?')).')';array_push($p,...$values);}}
if(in_array($grade,['A','B','C'],true)){$where.=' AND b.grade=?';$p[]=$grade;}
$pn=max(1,min(10000,(int)($_GET['p']??1)));$offset=($pn-1)*12;$count=0;if(ready()){$count=(int)Db::scalar('SELECT COUNT(*) FROM batches b JOIN materials m ON m.id=b.material_id JOIN hubs h ON h.id=b.hub_id WHERE '.$where,$p);$rows=Db::all('SELECT b.*,m.name_ar,m.name_en,m.icon,h.name_ar AS hub_ar,h.name_en AS hub_en,h.governorate FROM batches b JOIN materials m ON m.id=b.material_id JOIN hubs h ON h.id=b.hub_id WHERE '.$where.' ORDER BY b.created_at DESC LIMIT 12 OFFSET '.$offset,$p);}
$params=['material'=>$materials,'governorate'=>$govs,'subcategory'=>$subcategories,'grade'=>$grade];
?>
<section class="page-hero container market-hero"><div class="eyebrow"><?= t('قرار توريد مبني على بيانات مفحوصة','INSPECTED DATA FOR SUPPLY DECISIONS') ?></div><h1><?= t('سوق مخلفات المحاصيل','Crop-residue marketplace') ?></h1><p><?= t('اختر أكثر من محافظة وفئة وشكل تجهيز في البحث نفسه. تظهر التكلفة الكاملة قبل تثبيت الحجز.','Combine governorates, categories and preparation forms in one search. Full cost is shown before reservation.') ?></p></section>
<section class="container page-section"><?php if(!$commerce['available']): ?><div class="note warning"><?= icon('clock') ?><p><b><?= t('التصفح متاح، والحجز متوقف مؤقتاً.','Browsing is available; reservation is temporarily unavailable.') ?></b> <?= t('لم تكتمل جاهزية الإطلاق أو وجهة الدفع. تواصل مع الدعم إذا أردت تسجيل احتياجك.','Launch or payment readiness is incomplete. Contact support to record your requirement.') ?></p></div><?php endif; ?><form method="get" class="filter-panel"><input type="hidden" name="page" value="market"><fieldset><legend><?= t('فئة المادة','Material category') ?></legend><div class="filter-checks"><?php foreach($catalogue as $m):$v=(string)$m['id']; ?><label><input type="checkbox" name="material[]" value="<?= e($v) ?>" <?= in_array($v,$materials,true)?'checked':'' ?>><?= e(localized($m)) ?></label><?php endforeach; ?></div></fieldset><fieldset><legend><?= t('المحافظات — اختيار متعدد','Governorates — multiple selection') ?></legend><div class="filter-checks filter-scroll"><?php foreach(governorates() as $key=>$labels): ?><label><input type="checkbox" name="governorate[]" value="<?= e($key) ?>" <?= in_array($key,$govs,true)?'checked':'' ?>><?= e(t($labels[0],$labels[1])) ?></label><?php endforeach; ?></div></fieldset><fieldset><legend><?= t('شكل التجهيز','Preparation form') ?></legend><div class="filter-checks"><?php foreach(material_subcategories() as $key=>$labels): ?><label><input type="checkbox" name="subcategory[]" value="<?= e($key) ?>" <?= in_array($key,$subcategories,true)?'checked':'' ?>><?= e(t($labels[0],$labels[1])) ?></label><?php endforeach; ?></div></fieldset><label class="field"><span><?= t('درجة الفحص','Physical grade') ?></span><select name="grade"><option value=""><?= t('كل الدرجات','All grades') ?></option><?php foreach(['A','B','C'] as $g): ?><option <?= $grade===$g?'selected':'' ?>><?= $g ?></option><?php endforeach; ?></select></label><div class="filter-actions"><button class="button button-green"><?= icon('search') ?><?= t('تطبيق المرشحات','Apply filters') ?></button><a class="button button-outline" href="<?= e(url('market')) ?>"><?= t('مسح الاختيارات','Clear') ?></a></div></form><div class="market-result-heading"><span><?= $count ?> <?= t('دفعة متاحة','available batches') ?></span><span><?= icon('shield') ?><?= t('أربع فئات عرض معتمدة','Four approved presentation categories') ?></span></div>
<?php if(!$rows): ?><div class="empty-state"><?= icon('wheat') ?><h2><?= t('لا توجد دفعات مطابقة حالياً.','No matching batches right now.') ?></h2><p><?= t('غيّر مجموعة المرشحات أو أرسل احتياج المصنع لفريق حصاد.','Adjust the filter combination or send your factory requirement to Hasad.') ?></p><a href="<?= e(url('contact')) ?>" class="button button-green"><?= t('سجّل احتياجك','Record your requirement') ?></a></div><?php else: ?><div class="listing-grid"><?php foreach($rows as $i=>$b): ?><article class="listing-card"><div class="listing-art material-art-<?= $i%4 ?>"><?= icon($b['icon']) ?><span class="badge badge-published"><?= t('درجة','Grade') ?> <?= e($b['grade']) ?></span></div><div class="listing-body"><div class="listing-meta"><span><?= e(gov_label($b['governorate'])) ?> · <?= e(subcategory_label($b['subcategory'])) ?></span><small><?= e($b['code']) ?></small></div><h2><?= e(localized($b)) ?></h2><p><?= e($b['hub_'.lang()]) ?></p><div class="listing-stats"><div><small><?= t('المتاح','Available') ?></small><b><?= qty((int)$b['quantity_g']-(int)$b['reserved_g']) ?></b></div><div><small><?= t('سعر الطن','Price / tonne') ?></small><b><?= money((int)$b['price_per_tonne']) ?></b></div></div><?php if($commerce['available']): ?><a class="button button-green button-full" href="<?= e(url('checkout',['id'=>$b['id']])) ?>"><?= t('راجع وثبّت الطلب','Review & reserve') ?><?= icon('arrow') ?></a><?php else: ?><span class="button button-outline button-full" aria-disabled="true"><?= t('الحجز غير متاح حالياً','Reservation unavailable') ?></span><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
<?php if($count>12): ?><div class="pagination"><?php if($pn>1): ?><a class="button button-outline button-small" href="<?= e(url('market',$params+['p'=>$pn-1])) ?>"><?= t('السابق','Previous') ?></a><?php endif; ?><span><?= $pn ?> / <?= (int)ceil($count/12) ?></span><?php if($pn*12<$count): ?><a class="button button-outline button-small" href="<?= e(url('market',$params+['p'=>$pn+1])) ?>"><?= t('التالي','Next') ?></a><?php endif; ?></div><?php endif; ?><div class="note"><?= icon('shield') ?><p><?= t('الفئة وشكل التجهيز ودرجة الفحص أوصاف تشغيلية؛ ملاءمة الاستخدام النهائي تتطلب اعتماد المشتري والفحوص ذات الصلة.','Category, preparation and grade are operational descriptors; final-use suitability requires buyer approval and relevant tests.') ?></p></div></section>
